package uk.ac.ravensbourne.casevault.service;
import com.google.crypto.tink.*; import com.google.crypto.tink.aead.AeadConfig; import java.io.*; import java.nio.file.*; import java.security.*; import java.util.*; import org.apache.tika.Tika; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import uk.ac.ravensbourne.casevault.audit.AuditService; import uk.ac.ravensbourne.casevault.domain.*; import uk.ac.ravensbourne.casevault.repository.*; import uk.ac.ravensbourne.casevault.security.UserPrincipal; import uk.ac.ravensbourne.casevault.storage.ScanService;
/** Fail-closed evidence validation, Tink AEAD storage and service-layer authorisation (CWE-434/CWE-639). */
@Service public class EvidenceService { private static final long MAX=10*1024*1024; private static final Map<String,String> TYPES=Map.of("txt","text/plain","log","text/plain","csv","text/csv","json","application/json","pdf","application/pdf","png","image/png","jpg","image/jpeg","jpeg","image/jpeg"); private final CaseAccessService access; private final AccessPolicy policy; private final CaseRepository cases; private final EvidenceFileRepository files; private final UserAccountRepository users; private final AuditService audit; private final ScanService scan; private final Path root; private final Aead aead; private final Tika tika=new Tika(); public EvidenceService(CaseAccessService a,AccessPolicy p,CaseRepository c,EvidenceFileRepository f,UserAccountRepository u,AuditService au,ScanService s,@Value("${casevault.evidence.directory:uploads}") String dir,@Value("${casevault.evidence.tink-keyset-path:${TINK_KEYSET_PATH:}}") String keyset,@Value("${spring.profiles.active:}") String profile) throws Exception {access=a;policy=p;cases=c;files=f;users=u;audit=au;scan=s;root=Paths.get(dir).toAbsolutePath().normalize();Files.createDirectories(root);AeadConfig.register();aead=(keyset==null||keyset.isBlank())&&profile.contains("test")?KeysetHandle.generateNew(com.google.crypto.tink.aead.AeadKeyTemplates.AES256_GCM).getPrimitive(Aead.class):CleartextKeysetHandle.read(JsonKeysetReader.withPath(keyset)).getPrimitive(Aead.class);} public EvidenceFile upload(UserPrincipal p,UUID caseId,MultipartFile upload) throws Exception {var c=access.requireView(p,caseId);if(!policy.canUploadEvidence(p,c,cases.existsAssignment(caseId,p.id())))return deny(p,caseId,"policy");if(upload.isEmpty()||upload.getSize()>MAX||files.countByCaseRecordId(caseId)>=20)return deny(p,caseId,"size-or-count");String name=safe(upload.getOriginalFilename());String ext=name.substring(name.lastIndexOf('.')+1).toLowerCase(Locale.ROOT);if(!TYPES.containsKey(ext))return deny(p,caseId,"extension");byte[] plain=upload.getBytes();String detected=tika.detect(plain);if(!TYPES.get(ext).equals(detected)||executable(plain))return deny(p,caseId,"content-type");UUID id=UUID.randomUUID(),stored=UUID.randomUUID();byte[] cipher=aead.encrypt(plain,aad(caseId,id));Files.write(root.resolve(stored.toString()),cipher,StandardOpenOption.CREATE_NEW);var record=files.save(new EvidenceFile(id,c,name,stored,detected,plain.length,sha(plain),users.findById(p.id()).orElseThrow()));audit.record(p,"EVIDENCE_UPLOADED","EVIDENCE",id,"evidence-uploaded");return record;} public byte[] download(UserPrincipal p,UUID caseId,UUID id) throws Exception {var c=access.requireView(p,caseId);var f=files.findByIdAndCaseRecordId(id,caseId).orElseThrow(CaseNotFoundException::new);if(!policy.canDownloadEvidence(p,c,cases.existsAssignment(caseId,p.id())))throw new CaseNotFoundException();try{byte[] plain=aead.decrypt(Files.readAllBytes(root.resolve(f.getStoredName().toString())),aad(caseId,id));if(!sha(plain).equals(f.getSha256()))throw new GeneralSecurityException();audit.record(p,"EVIDENCE_DOWNLOADED","EVIDENCE",id,"evidence-downloaded");return plain;}catch(Exception e){audit.record(p,"EVIDENCE_REJECTED","EVIDENCE",id,"integrity-failed");throw new CaseNotFoundException();}} private EvidenceFile deny(UserPrincipal p,UUID id,String r){audit.record(p,"EVIDENCE_REJECTED","CASE",id,r);throw new IllegalArgumentException("Evidence rejected");} private static String safe(String s){String n=Paths.get(s==null?"file":s).getFileName().toString().replaceAll("[\\p{Cntrl}]","");if(n.contains("..")||n.indexOf('.')!=n.lastIndexOf('.'))throw new IllegalArgumentException("Invalid filename");return n;} private static boolean executable(byte[] b){return b.length>3&&((b[0]=='M'&&b[1]=='Z')||(b[0]==0x7f&&b[1]=='E'&&b[2]=='L'&&b[3]=='F'));} private static byte[] aad(UUID c,UUID f){return (c+":"+f).getBytes(java.nio.charset.StandardCharsets.UTF_8);} private static String sha(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));} }
